const inputItems = $input.all();
const countryItems = $('Split Countries').all();
let results = [];
inputItems.forEach((item, idx) => {
  const country = countryItems[idx] ? countryItems[idx].json.country : 'unknown';
  const topic = countryItems[idx] ? countryItems[idx].json.topic : '';
  const organic = item.json.organic || [];
  const top = organic.slice(0, 3);
  top.forEach(r => {
    results.push({ json: { topic, country, url: r.link, title: r.title } });
  });
});
return results;

