const countries = [...new Set($('Split Countries').all().map(i => i.json.country))];

const prompt = `You are an SEO researcher. Topic: "${topic}". Target countries: ${countries.join(', ')}.
Below is scraped competitor page data (title, meta, h1, h2, body text) collected separately for EACH target country.
Extract:
1. "keywords": AT LEAST 30 relevant SEO keywords/phrases (mix of short-tail and long-tail), covering ALL the target countries listed above (not just one). Each with an estimated relevance score 1-10 and which country/countries it appeared strongly in.
2. "entities": 15-25 related named entities/topics (people, brands, concepts, tools) relevant to this niche, based on what the top competitor pages talk about.
Return ONLY valid JSON, no markdown, no explanation, in this exact shape:
{"keywords":[{"keyword":"","score":0,"countries":[""]}],"entities":[{"entity":"","type":""}]}

Competitor data (grouped across countries):
${JSON.stringify(items).slice(0, 14000)}`;

return [{ json: { prompt } }];

