const data = $json;
const keywords = (data.keywords || []).sort((a,b) => b.score - a.score);
const best = keywords.slice(0, 15).map(k => k.keyword);
const rows = keywords.map(k => ({ json: {
  keyword: k.keyword,
  score: k.score,
  countries: (k.countries||[]).join(', '),
  is_best: best.includes(k.keyword) ? 'YES' : ''
} }));
return rows;

const topic = $('Form Trigger').first().json['Topic'];
const website = $('Form Trigger').first().json['Website URL'];
const bestKeywords = $('Score & Format Keywords').all()
  .filter(i => i.json.is_best === 'YES')
  .map(i => i.json.keyword);
const entities = $('Format Entities').all().map(i => i.json.entity);
const siteInfo = ($('Parse Target Website Content').all()[0] || { json: {} }).json;

const prompt = `You are writing an SEO article for the website "${website}".

First, here is what THIS website is actually about (scraped from its homepage):
Title: ${siteInfo.pageTitle || 'N/A'}
Meta description: ${siteInfo.metaDescription || 'N/A'}
Headings: ${[].concat(siteInfo.h1||[], siteInfo.h2||[]).join(', ') || 'N/A'}
Body excerpt: ${(siteInfo.bodyText||'').slice(0,1500)}

Based on the above, figure out what this business actually does (its core service/product/purpose) and write content that fits THAT business specifically. For example, if it is a service-based business, describe the services offered, how the process/workflow works, and other sections relevant to a service business. If it sells products, focus on products/benefits instead. Adapt the structure to match the real nature of this specific site — do not write generic filler.

Topic to write about: "${topic}"
Use these best keywords naturally throughout, each at least once: ${bestKeywords.join(', ')}
Include these related entities/concepts where relevant, each at least once: ${entities.join(', ')}

Structure required:
- SEO Title (under 60 chars)
- Meta Description (under 155 chars)
- H1
- Multiple H2/H3 sections matching the website's actual business/services
- Intro paragraph with primary keyword in first 100 words
- Conclusion with a call to action
- 900-1300 words total

Return ONLY valid JSON in this shape:
{"seo_title":"","meta_description":"","content_markdown":""}`;

return [{ json: { prompt } }];

let text = $json.candidates[0].content.parts[0].text;
text = text.replace(/```json|```/g, '').trim();
let article;
try { article = JSON.parse(text); } catch (e) { article = { seo_title: '', meta_description: '', content_markdown: text }; }

const bestKeywords = $('Score & Format Keywords').all()
  .filter(i => i.json.is_best === 'YES')
  .map(i => i.json.keyword.toLowerCase());
const entities = $('Format Entities').all().map(i => i.json.entity.toLowerCase());

const body = (article.content_markdown || '').toLowerCase();
const wordCount = body.split(/\s+/).filter(Boolean).length;
const keywordHits = bestKeywords.filter(k => body.includes(k));
const missingKeywords = bestKeywords.filter(k => !body.includes(k));
const entityHits = entities.filter(e => body.includes(e));
const missingEntities = entities.filter(e => !body.includes(e));
const first100 = body.split(/\s+/).slice(0,100).join(' ');

const checklist = {
  seo_title_length_ok: (article.seo_title||'').length <= 60,
  meta_description_length_ok: (article.meta_description||'').length <= 155,
  has_h1: /^#\s/m.test(article.content_markdown || ''),
  has_h2_or_h3: /^##\s|^###\s/m.test(article.content_markdown || ''),
  word_count: wordCount,
  word_count_ok: wordCount >= 900,
  keywords_used: keywordHits.length + ' / ' + bestKeywords.length,
  missing_keywords: missingKeywords.join(', '),
  entities_used: entityHits.length + ' / ' + entities.length,
  missing_entities: missingEntities.join(', '),
  primary_keyword_in_intro: bestKeywords.length ? first100.includes(bestKeywords[0]) : false
};

return [{ json: { ...article, ...checklist } }];

const raw = $('Run SEO Checklist').item.json.content_markdown || '';
const lines = raw.split('\n');

let plainText = '';
let requests = [];
let cursor = 1;

function processLine(line) {
  let level = 0;
  let text = line;
  const h3 = /^###\s+(.*)/.exec(line);
  const h2 = /^##\s+(.*)/.exec(line);
  const h1 = /^#\s+(.*)/.exec(line);
  if (h3) { level = 3; text = h3[1]; }
  else if (h2) { level = 2; text = h2[1]; }
  else if (h1) { level = 1; text = h1[1]; }

  let boldRanges = [];
  let cleaned = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '*' && text[i+1] === '*') {
      const end = text.indexOf('**', i + 2);
      if (end !== -1) {
        const boldText = text.slice(i + 2, end);
        const start = cleaned.length;
        cleaned += boldText;
        boldRanges.push({ start, end: cleaned.length });
        i = end + 2;
        continue;
      }
    }
    cleaned += text[i];
    i++;
  }
  return { level, text: cleaned, boldRanges };
}

for (const line of lines) {
  const { level, text, boldRanges } = processLine(line);
  const lineStart = cursor;
  plainText += text + '\n';
  const lineEnd = cursor + text.length;

  if (level > 0) {
    requests.push({
      updateParagraphStyle: {
        range: { startIndex: lineStart, endIndex: lineEnd + 1 },
        paragraphStyle: { namedStyleType: level === 1 ? 'HEADING_1' : level === 2 ? 'HEADING_2' : 'HEADING_3' },
        fields: 'namedStyleType'
      }
    });
  }
  boldRanges.forEach(b => {
    requests.push({
      updateTextStyle: {
        range: { startIndex: lineStart + b.start, endIndex: lineStart + b.end },
        textStyle: { bold: true },
        fields: 'bold'
      }
    });
  });
  cursor = lineEnd + 1;
}

const allRequests = [{ insertText: { location: { index: 1 }, text: plainText } }, ...requests];
return [{ json: { requests: allRequests } }];
